  // parallax
  let tick0 = false; const onScroll = () => { if (tick0) return; tick0 = true; requestAnimationFrame(() => { root.style.setProperty("--sy", reduce ? 0 : Math.min(1200, scrollY)); tick0 = false; }); };
  addEventListener("scroll", onScroll, { passive: true });

