    cards.forEach((c, i) => { const d = (c.offsetLeft + c.offsetWidth / 2 - mid) / 266, ab = Math.abs(d); if (ab < bd) { bd = ab; best = i; } const k = Math.max(-2.2, Math.min(2.2, d)), ak = Math.min(1, Math.abs(k));
      c.style.transform = reduce ? "" : `rotateY(${-k * 22}deg) translateZ(${-Math.abs(k) * 60}px) scale(${1 - ak * 0.1})`; c.style.opacity = 1 - ak * 0.45; c.style.zIndex = 10 - Math.round(Math.abs(k)); });
