  const waText = (d) => [`RSVP · ${C.title}`, `Name: ${d.name}`, `Phone: ${d.phone}`, d.attending ? `Attending: Yes, ${d.guests} guest${d.guests > 1 ? "s" : ""}` : "Attending: No, with regrets", d.attending && `Events: ${d.events.join(", ")}`, d.note && `Note: ${d.note}`].filter(Boolean).join("\n");
